namespace {
	typedef pair<CHRPOS, CHRPOS> overlapInterval;

	struct BlockedHit {
		Record *record;
		vector<overlapInterval> overlaps;
		CHRPOS overlapBases;
		bool sufficientFractionA;
		bool sufficientFractionB;
	};

	CHRPOS mergeAndMeasure(vector<overlapInterval> &overlaps)
	{
		if (overlaps.empty()) {
			return 0;
		}

		sort(overlaps.begin(), overlaps.end());
		vector<overlapInterval> merged;
		merged.push_back(overlaps[0]);
		for (size_t i = 1; i < overlaps.size(); i++) {
			overlapInterval &last = merged.back();
			if (overlaps[i].first <= last.second) {
				last.second = max(last.second, overlaps[i].second);
			} else {
				merged.push_back(overlaps[i]);
			}
		}
		overlaps.swap(merged);

		CHRPOS total = 0;
		for (size_t i = 0; i < overlaps.size(); i++) {
			total += overlaps[i].second - overlaps[i].first;
		}
		return total;
	}
}

