 28		CHRPOS mergeAndMeasure(vector<overlapInterval> &overlaps)
 29		{
 30			if (overlaps.empty()) {
 31				return 0;
 32			}
 33	
 34			sort(overlaps.begin(), overlaps.end());
 35			vector<overlapInterval> merged;
 36			merged.push_back(overlaps[0]);
 37			for (size_t i = 1; i < overlaps.size(); i++) {
 38				overlapInterval &last = merged.back();
 39				if (overlaps[i].first <= last.second) {
 40					last.second = max(last.second, overlaps[i].second);
 41				} else {
 42					merged.push_back(overlaps[i]);
 43				}
 44			}
 45			overlaps.swap(merged);
 46	
 47			CHRPOS total = 0;
 48			for (size_t i = 0; i < overlaps.size(); i++) {
 49				total += overlaps[i].second - overlaps[i].first;
 50			}
 51			return total;
 52		}
