bool NewChromSweep::intersects(const Record *rec1, const Record *rec2) const
{
    //return rec1->sameChromIntersects(rec2, _context->getSameStrand(), _context->getDiffStrand(),
    //        _context->getOverlapFraction(), _context->getReciprocal());
    // The sweep uses outer record spans to discover candidates.  Applying
    // fractions here would discard split records before their aligned blocks
    // can be measured by BlockMgr.
    float overlapFractionA = _context->getObeySplits()
        ? 0.0f : _context->getOverlapFractionA();
    float overlapFractionB = _context->getObeySplits()
        ? 0.0f : _context->getOverlapFractionB();
    return rec1->sameChromIntersects(rec2,
                                     _context->getSameStrand(),
                                     _context->getDiffStrand(),
                                     overlapFractionA,
                                     overlapFractionB,
                                     _context->getReciprocalFraction(),
                                     _context->getEitherFraction());
}


